package com.bananalab.lite;
import android.app.*;import android.os.Bundle;import android.view.*;import android.widget.*;import android.graphics.Typeface;import java.util.*;
/** Applies a local, compiled font choice to native app text, including dialogs. */
final class UiTypeface{
 static final String[] FAMILIES={"original","sans-serif","serif","monospace","sans-serif-medium"};
 static final WeakHashMap<TextView,Typeface> original=new WeakHashMap<>();static final WeakHashMap<View,Boolean> listening=new WeakHashMap<>();
 static void apply(View root){if(root==null)return;int font=ModularHub.view().font;if(root instanceof TextView){TextView t=(TextView)root;if(!original.containsKey(t))original.put(t,t.getTypeface()==null?Typeface.DEFAULT:t.getTypeface());Typeface old=original.get(t),now=t.getTypeface();Typeface selected=font==0?old:Typeface.create(FAMILIES[font],now==null?0:now.getStyle());if(now!=selected&&(now==null||!now.equals(selected)))t.setTypeface(selected);}if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++)apply(g.getChildAt(i));}}
 static void listen(final View root){if(root==null)return;apply(root);if(listening.containsKey(root))return;listening.put(root,true);root.getViewTreeObserver().addOnGlobalLayoutListener(new ViewTreeObserver.OnGlobalLayoutListener(){public void onGlobalLayout(){apply(root);}});}
 static void install(Application app){app.registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){listen(a.getWindow().getDecorView());}public void onActivityResumed(Activity a){listen(a.getWindow().getDecorView());}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){listening.remove(a.getWindow().getDecorView());}});}
 static <T extends Dialog>T show(T dialog){dialog.show();if(dialog.getWindow()!=null)listen(dialog.getWindow().getDecorView());return dialog;}
 static AlertDialog show(AlertDialog.Builder builder){return show(builder.create());}
 static String command(String input){String q=NaturalCoding.normalize(input);if(q.startsWith("no ")||q.matches("^(como|por que|que pasa) .*"))return null;
  if(!q.matches("(?s).*(?:fuente|tipografia|tipo de letra).*"))return null;
  boolean action=q.matches("^(?:cambia|cambiar|cambies|usa|usar|uses|pone|poner|elegi|elige|elegir|hace|haz|quiero|necesito) .*" );if(!action)return null;
  String font=null;if(q.matches("(?s).*(?:que vos elijas|que tu elijas|que elijas|de tu eleccion|a tu eleccion|a tu gusto|elige vos|elegi vos|la que quieras|que prefieras).*"))font="sans-serif-medium";else if(q.matches("(?s).*\\b(?:monospace|monoespaciada|monoespaciado)\\b.*"))font="monospace";else if(q.contains("sans serif medium")||q.contains("sans serif media"))font="sans-serif-medium";else if(q.contains("sans serif")||q.contains("sin serif"))font="sans-serif";else if(q.matches("(?s).*\\bserif\\b.*"))font="serif";else if(q.matches("(?s).*\\b(?:original|predeterminada|predeterminado)\\b.*"))font="original";
  if(font==null)throw new IllegalArgumentException("Puedo elegir una fuente por vos o usar sans serif, serif, monospace u original. No cambié la interfaz.");
  String residue=q.replaceAll("\\b(?:cambia|cambiar|cambies|usa|usar|uses|pone|poner|elegi|elige|elegir|hace|haz|quiero|necesito|todos|todas|todo|toda|los|las|el|la|de|del|en|a|por|para|textos|texto|fuente|fuentes|tipografia|tipo|letra|letras|app|aplicacion|banana|chat|interfaz|una|un|que|vos|elijas|tu|gusto|eleccion|quieras|prefieras|sans|serif|medium|media|sin|monospace|monoespaciada|monoespaciado|original|predeterminada|predeterminado|mas|linda|bonita|con)\\b"," ").replaceAll("\\s+"," ").trim();if(!residue.isEmpty())throw new IllegalArgumentException("No entendí esta parte del cambio de fuente: "+residue+". No apliqué un pedido parcial.");return "pone la fuente de la app "+font;}
}
